contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address recipient) public {
        // ensure C holds funds so a withdrawal would be observable
        require(address(c).balance > 0);

        uint256 bal0 = address(this).balance;

        // attempt an unauthorized withdrawAll; capture revert instead of propagating
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));

        // General rule: if the call reverted (unauthorized caller), no funds
        // may have been transferred out to the recipient.
        // P: require fails before any transfer -> nothing leaves C.
        // M: transfer executes before the check, moving C's balance to recipient.
        assert(!ok || address(c).balance == 0);
    }
}

