contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable _recipient) public {
        require(address(c).balance == 0);
        require(_recipient == payable(address(c)));
        bool reverted;
        try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
        // c itself has a payable fallback, so it accepts transfers of any value.
        // With balance 0, P transfers 0 wei (always succeeds); M transfers 1 wei (fails).
        assert(!reverted);
    }
}

